import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int a = sc.nextInt();
        int b = sc.nextInt();

        int posAna = a % 3;
        int posBeatriz = b % 3;

        if (posBeatriz == posAna) {
            posBeatriz = (posBeatriz + 1) % 3;
        }

        int posCarolina = 3 - posAna - posBeatriz;

        System.out.println(posCarolina);
    }
}
